-- IPA 2020-12-13 FE exemption fundamentals; additive, attributed adaptations.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q03','exam-fe','ビット演算','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問3・改編】8ビットのビット列について、下位4ビットが変化しない操作はどれか。','[{"id":"a","text":"16進0Fとの排他的論理和"},{"id":"b","text":"16進0Fとの否定論理積"},{"id":"c","text":"16進0Fとの論理積"},{"id":"d","text":"16進0Fとの論理和"}]','"c"','0Fの下位4ビットは全て1なので、ANDをとっても元の下位4ビットは変わらない。 中文解析：0F的低四位全为1，与其进行AND运算可保留原来的低四位。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q05','exam-fe','平均符号長','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問5・改編】文字A〜Eの符号と出現確率はA:0（50％）、B:10（30％）、C:110（10％）、D:1110（5％）、E:1111（5％）。1文字当たり平均何ビットか。','[{"id":"a","text":"1.6"},{"id":"b","text":"1.8"},{"id":"c","text":"2.5"},{"id":"d","text":"2.8"}]','"b"','1×0.5＋2×0.3＋3×0.1＋4×0.05＋4×0.05＝1.8ビット。 中文解析：按出现概率加权：0.5＋0.6＋0.3＋0.2＋0.2＝1.8位。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q06','exam-fe','パリティ検査','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問6・改編】伝送誤りに対処する垂直パリティ方式の説明として適切なものはどれか。','[{"id":"a","text":"1ビットの誤りを検出できる"},{"id":"b","text":"1ビットの誤りを訂正でき、2ビットの誤りも検出できる"},{"id":"c","text":"奇数パリティは1ビット誤りを検出できるが偶数パリティはできない"},{"id":"d","text":"奇数パリティは奇数個、偶数パリティは偶数個のビット誤りを検出する"}]','"a"','垂直パリティは奇数個のビット反転を検出でき、単独では誤り位置を特定して訂正できない。偶数個の反転は見逃し得る。 中文解析：垂直奇偶校验可检测奇数个位反转，包括一位错误，但单独不能定位纠错，偶数个位错误可能漏检。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q07','exam-fe','キュー','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問7・改編】キューの説明として適切なものはどれか。','[{"id":"a","text":"最後に格納したデータを最初に取り出す"},{"id":"b","text":"最初に格納したデータを最初に取り出す"},{"id":"c","text":"添字によって特定データを参照する"},{"id":"d","text":"複数ポインタによって階層関係を表す"}]','"b"','キューは先入れ先出し（FIFO）。最後に入れたものを先に取り出すのはスタックのLIFO。 中文解析：队列采用先进先出FIFO；后进先出LIFO是栈的特征。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q09','exam-fe','最大公約数','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問9・改編】x>y≧0の整数に対し、F(x,y)はy=0ならx、それ以外はF(y,x mod y)とする。F(231,15)の値はどれか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"5"},{"id":"d","text":"7"}]','"b"','231 mod 15＝6、15 mod 6＝3、6 mod 3＝0なので、最大公約数3が返る。 中文解析：欧几里得算法的余数依次为6、3、0，因此返回3。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q10','exam-fe','二分探索','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問10・改編】顧客番号をキーに二分探索を使うのに適したデータ配置はどれか。','[{"id":"a","text":"顧客番号から求めたハッシュ値の位置に配置する"},{"id":"b","text":"顧客番号と無関係にランダムに配置する"},{"id":"c","text":"顧客番号の昇順に配置する"},{"id":"d","text":"顧客番号をセルに格納しセルのアドレス順に配置する"}]','"c"','二分探索はキー順に整列されたデータの中央を比較し、探索範囲を半分ずつ絞る。 中文解析：二分查找需要数据按查找键排序，比较中间元素后逐步缩小范围。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q11','exam-fe','命令パイプライン','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問11・改編】RISCの5段パイプラインで、①書込み②実行とアドレス生成③命令デコードとレジスタ読出し④命令フェッチ⑤メモリアクセスを行う順序はどれか。','[{"id":"a","text":"③④②⑤①"},{"id":"b","text":"③⑤②④①"},{"id":"c","text":"④③②⑤①"},{"id":"d","text":"④⑤③②①"}]','"c"','命令フェッチ→デコードとレジスタ読出し→実行・アドレス生成→メモリアクセス→書込みの順。 中文解析：依次为取指、译码和读寄存器、执行及地址生成、访问内存、写回。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q13','exam-fe','キャッシュヒット率','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問13・改編】主記憶アクセス60ns、キャッシュアクセス10nsで、キャッシュ経由の実効アクセス時間が15ns。ヒット率はいくらか。','[{"id":"a","text":"0.1"},{"id":"b","text":"0.17"},{"id":"c","text":"0.83"},{"id":"d","text":"0.9"}]','"d"','ヒット率hとして10h＋60(1−h)＝15を解くとh＝0.9。 中文解析：设命中率h，按10h＋60(1−h)＝15计算，h＝0.9。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q14','exam-fe','RAID1','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問14・改編】RAID1で4TBのデータを格納する。フォーマット後1TBの磁気記憶装置は少なくとも何台必要か。','[{"id":"a","text":"4"},{"id":"b","text":"5"},{"id":"c","text":"6"},{"id":"d","text":"8"}]','"d"','RAID1はデータを二重化する。実効4TBには1TB装置が4組、計8台必要。 中文解析：RAID1镜像需要两份数据，4TB有效容量需要8个1TB磁盘。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q15','exam-fe','フォールトトレランス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問15・改編】フォールトトレラントシステムの説明として適切なものはどれか。','[{"id":"a","text":"一部が故障してもシステム全体として必要な機能を維持する"},{"id":"b","text":"地域災害に備えて遠隔地に予備を用意する"},{"id":"c","text":"複数プロセッサをネットワークでつなぎ資源を共有する"},{"id":"d","text":"複数プロセッサで同一取引を並行処理し結果を照合する"}]','"a"','フォールトトレランスは構成要素に障害が起きても、システム全体として機能を継続する性質である。 中文解析：容错系统在部分组件故障时仍能保持整体必要功能。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q16','exam-fe','MTBF・MTTR','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問16・改編】MTBFとMTTRの説明として適切なものはどれか。','[{"id":"a","text":"エラーログや命令トレース機能によってMTTRは長くなる"},{"id":"b","text":"遠隔保守によってMTBFは短くなりMTTRは長くなる"},{"id":"c","text":"装置の種類が多いほどMTBFは長くなる"},{"id":"d","text":"予防保守によってMTBFは長くなる"}]','"d"','予防保守により故障の発生間隔を伸ばすことを期待できる。MTBFは平均故障間隔、MTTRは平均修復時間である。 中文解析：预防性维护有助于延长平均故障间隔MTBF；MTTR是平均修复时间。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
